```js
const Typesense = require('typesense')

// Create a client
const typesense = new Typesense.Client({
  nodes: [
    {
      host: 'localhost',
      port: '8108',
      protocol: 'http'
    }
  ],
  apiKey: 'xyz',
  numRetries: 3, // A total of 4 tries (1 original try + 3 retries)
  connectionTimeoutSeconds: 120, // Set a longer timeout for large imports
  logLevel: 'debug'
})

async function runExample () {
  try {
    // Delete if the collection already exists from a previous example run
    await typesense.collections('test').delete()
  } catch (error) {
    // do nothing
  }

  try {
    let result
    // create a collection
    result = await typesense.collections().create({ name: "test", fields: [{ name: "japanese", type: "string", locale: "ja" }] });
    console.log(result)

    // create a document
    result = await typesense
      .collections("test")
      .documents()
      .import([{ japanese: "こんにちは" }, { japanese: "またね" }], { action: "upsert" });
    console.log(result)
  } catch (error) {
    console.log(error)
  } finally {
    // Cleanup
    typesense.collections('test').delete()
  }
}

async function timer (seconds) {
  return new Promise((resolve) => setTimeout(resolve, seconds * 1000))
}

runExample()
```

